from itertools import permutations

def check_free_block(perm, n, k):
    """Check if there's a k×k contiguous free block for permutation perm."""
    for r in range(n - k + 1):
        for c in range(n - k + 1):
            # Block: rows r..r+k-1, cols c..c+k-1
            free = True
            for i in range(r, r + k):
                if c <= perm[i] - 1 < c + k:  # perm[i] is 1-indexed column
                    free = False
                    break
            if free:
                return True
    return False

def find_max_k(n):
    """Find the max k such that every permutation has a k×k free block."""
    best_k = 0
    for k in range(1, n + 1):
        all_ok = True
        for perm in permutations(range(1, n + 1)):
            if not check_free_block(perm, n, k):
                all_ok = False
                # Find a counterexample
                break
        if all_ok:
            best_k = k
        else:
            break  # If k doesn't work, k+1 won't either
    return best_k

for n in range(2, 10):
    k = find_max_k(n)
    print(f"n={n}: k={k}")
