def has_free_block(perm, n, k):
    for r in range(n - k + 1):
        cols = set(perm[i] for i in range(r, r + k))
        for c in range(1, n - k + 2):
            if cols.isdisjoint(set(range(c, c + k))):
                return (r, c)
    return None

# For cases where gcd(k,n) != 1 and n is not k^2, try various constructions
def try_multiply(n, k, a):
    """Try sigma(i) = (a*(i-1)) % n + 1"""
    if gcd(a, n) != 1:
        return None
    perm = [(a * (i - 1)) % n + 1 for i in range(1, n + 1)]
    if sorted(perm) != list(range(1, n + 1)):
        return None
    return perm

def try_transpose_modified(n, k):
    """Try modified transpose for n < k^2"""
    # Arrange n elements in a grid with k columns
    # Row a, col b -> position a*k + b + 1
    # Transpose: position b*k + a + 1... but need to handle n < k^2
    # Use: sigma(a*k + b + 1) = b * ceil(n/k) + a + 1, for valid positions
    cols_per_row = math.ceil(n / k)
    perm = [0] * n
    for i in range(n):
        a = i // k  # macro-row
        b = i % k   # macro-col
        # Check if this position is valid (a*k + b < n)
        if a * k + b >= n:
            continue
        val = b * cols_per_row + a + 1
        if val > n:
            return None
        perm[i] = val
    if 0 in perm or sorted(perm) != list(range(1, n + 1)):
        return None
    return perm

# Brute force search for small n
for n in [2, 6, 10, 12, 14]:
    k = int(math.isqrt(n - 1)) + 1
    found = False
    for perm in permutations(range(1, n + 1)):
        if has_free_block(perm, n, k) is None:
            print(f"n={n}, k={k}: counterexample = {perm}")
            found = True
            break
    if not found:
        print(f"n={n}, k={k}: NO counterexample found!")

# Try multiply with different a values for harder cases
for n in [10, 12, 14, 20, 26, 27, 28]:
    k = int(math.isqrt(n - 1)) + 1
    for a in range(1, n):
        perm = try_multiply(n, k, a)
        if perm and has_free_block(perm, n, k) is None:
