import math
from math import gcd

def has_free_block(perm, n, k):
    for r in range(n - k + 1):
        cols = set(perm[i] for i in range(r, r + k))
        for c in range(1, n - k + 2):
            if cols.isdisjoint(set(range(c, c + k))):
                return (r, c)
    return None

def transpose_construction(n, k):
    """Build permutation by transposing a q×k grid (q = ceil(n/k))"""
    q = math.ceil(n / k)
    # Grid: row a, col b -> value a*k + b + 1 (for a*k + b < n)
    # Transpose: read column by column
    perm = []
    for b in range(k):
        for a in range(q):
            idx = a * k + b
            if idx < n:
                perm.append(idx + 1)
    return perm

# Test transpose construction for all n
for n in range(2, 100):
    k = int(math.isqrt(n - 1)) + 1
    perm = transpose_construction(n, k)
    assert sorted(perm) == list(range(1, n + 1)), f"Not a permutation for n={n}: {perm}"
    result = has_free_block(perm, n, k)
    if result is None:
        pass  # Works
    else:
        print(f"n={n}, k={k}: transpose FAILS, free block at {result}")

print("All tested up to n=99. Checking which ones work...")
